from bs4 import BeautifulSoup

# Function to extract text from an HTML file
def extract_text_from_html(file_path):
    with open(file_path, 'r', encoding='utf-8') as file:
        soup = BeautifulSoup(file, 'html.parser')
        return soup.get_text()

# Initialize a dictionary to store the content of each file
file_contents = {}

# Extract text from each file
for file_name in extracted_files:
    file_path = os.path.join(extract_dir, file_name)
    if file_name.endswith('.html'):
        try:
            content = extract_text_from_html(file_path)
            file_contents[file_name] = content
        except Exception as e:
            file_contents[file_name] = f"Error reading file: {e}"

# Displaying the names of files and initial few lines of their content
summary_preview = {name: content[:500] for name, content in file_contents.items()}
