# Initialize placeholders for categories and insights
categories = {
    "Harmonic Models": [],
    "Recursive Frameworks": [],
    "Quantum Mechanics": [],
    "AI and Frameworks": [],
    "Physics and Universal Concepts": [],
    "Formulas and Calculations": [],
    "Insights and Reflections": []
}

# Categorize content by searching for thematic keywords and patterns
for file_name, content in file_contents.items():
    if "harmonic" in file_name.lower() or "resonance" in content.lower():
        categories["Harmonic Models"].append((file_name, content))
    if "recursive" in file_name.lower() or "framework" in content.lower():
        categories["Recursive Frameworks"].append((file_name, content))
    if "quantum" in file_name.lower() or "gravity" in content.lower():
        categories["Quantum Mechanics"].append((file_name, content))
    if "AI" in file_name or "Mark" in content:
        categories["AI and Frameworks"].append((file_name, content))
    if "universe" in content.lower() or "physics" in file_name.lower():
        categories["Physics and Universal Concepts"].append((file_name, content))
    if "formula" in file_name.lower() or "calculation" in content.lower():
        categories["Formulas and Calculations"].append((file_name, content))
    if "reflection" in file_name.lower() or "insight" in content.lower():
        categories["Insights and Reflections"].append((file_name, content))

# Summarize the categorized data
category_summaries = {category: len(files) for category, files in categories.items()}
category_summaries

